import java.io.Serializable;

public class TaskEvent implements Serializable {
    public long timestamp;
    public long jobId;
    public int taskIndex;
    public int eventType;

    public TaskEvent() {}

    public TaskEvent(long timestamp, long jobId, int taskIndex, int eventType) {
        this.timestamp = timestamp;
        this.jobId = jobId;
        this.taskIndex = taskIndex;
        this.eventType = eventType;
    }

    public static TaskEvent fromString(String line) {
        String[] tokens = line.split(",");
        if (tokens.length < 6) return null;
        try {
            long timestamp = tokens[0].isEmpty() ? 0 : Long.parseLong(tokens[0]);
            long jobId = tokens[2].isEmpty() ? 0 : Long.parseLong(tokens[2]);
            int taskIndex = tokens[3].isEmpty() ? 0 : Integer.parseInt(tokens[3]);
            int eventType = tokens[5].isEmpty() ? 0 : Integer.parseInt(tokens[5]);
            return new TaskEvent(timestamp, jobId, taskIndex, eventType);
        } catch (NumberFormatException e) {
            return null;
        }
    }
}

